import{_ as r,o,c as n,a0 as s}from"./chunks/framework.Bmhw_dvp.js";const d=JSON.parse('{"title":"Page 10","description":"","frontmatter":{},"headers":[],"relativePath":"page-10.md","filePath":"page-10.md"}'),l={name:"page-10.md"};function a(i,t,e,g,u,h){return o(),n("div",null,[...t[0]||(t[0]=[s('<h1 id="page-10" tabindex="-1">Page 10 <a class="header-anchor" href="#page-10" aria-label="Permalink to &quot;Page 10&quot;">​</a></h1><h3 id="排序算法" tabindex="-1">排序算法 <a class="header-anchor" href="#排序算法" aria-label="Permalink to &quot;排序算法&quot;">​</a></h3><h4 id="_1-冒泡排序-bubble-sort" tabindex="-1">① 冒泡排序 (bubble sort) <a class="header-anchor" href="#_1-冒泡排序-bubble-sort" aria-label="Permalink to &quot;① 冒泡排序 (bubble sort)&quot;">​</a></h4><ul><li><strong>思想</strong>：相邻元素两两比较，较大元素上浮，重复多次</li><li><strong>时间复杂度</strong>：最好 $O(n)$，最坏/平均 $O(n^2)$</li><li><strong>空间复杂度</strong>：$O(1)$，原地排序</li><li><strong>稳定性</strong>：稳定</li></ul><h4 id="_2-选择排序-selection-sort" tabindex="-1">② 选择排序 (selection sort) <a class="header-anchor" href="#_2-选择排序-selection-sort" aria-label="Permalink to &quot;② 选择排序 (selection sort)&quot;">​</a></h4><ul><li><strong>思想</strong>：每次选取最小元素放到已排序序列的末尾/开头</li><li><strong>时间复杂度</strong>：最好/最坏/平均 $O(n^2)$</li><li><strong>空间复杂度</strong>：$O(1)$，原地排序</li><li><strong>稳定性</strong>：不稳定</li></ul><h4 id="_3-插入排序-insertion-sort" tabindex="-1">③ 插入排序 (insertion sort) <a class="header-anchor" href="#_3-插入排序-insertion-sort" aria-label="Permalink to &quot;③ 插入排序 (insertion sort)&quot;">​</a></h4><ul><li><strong>思想</strong>：把当前元素插入到已排序子数组的正确位置</li><li><strong>时间复杂度</strong>：最好 $O(n)$，最坏/平均 $O(n^2)$</li><li><strong>空间复杂度</strong>：$O(1)$，原地排序</li><li><strong>稳定性</strong>：稳定</li></ul><h4 id="_4-快速排序-quick-sort" tabindex="-1">④ 快速排序 (quick sort) <a class="header-anchor" href="#_4-快速排序-quick-sort" aria-label="Permalink to &quot;④ 快速排序 (quick sort)&quot;">​</a></h4><ul><li><strong>思想</strong>：分治法，选择枢轴，将数组分为两部分递归排序</li><li><strong>时间复杂度</strong>：平均 $O(n log n)$，最坏 $O(n^2)$</li><li><strong>空间复杂度</strong>：$O(log n)$，递归栈</li><li><strong>稳定性</strong>：不稳定</li></ul><h4 id="_5-归并排序-merge-sort" tabindex="-1">⑤ 归并排序 (merge sort) <a class="header-anchor" href="#_5-归并排序-merge-sort" aria-label="Permalink to &quot;⑤ 归并排序 (merge sort)&quot;">​</a></h4><ul><li><strong>思想</strong>：分治法，递归分为两半，排序后合并</li><li><strong>时间复杂度</strong>：最好/最坏/平均 $O(n log n)$</li><li><strong>空间复杂度</strong>：$O(n)$，需要辅助数组</li><li><strong>稳定性</strong>：稳定</li></ul><h4 id="_6-计数排序-counting-sort" tabindex="-1">⑥ 计数排序 (counting sort) <a class="header-anchor" href="#_6-计数排序-counting-sort" aria-label="Permalink to &quot;⑥ 计数排序 (counting sort)&quot;">​</a></h4><ul><li><strong>思想</strong>：统计每个数值出现次数，累加计算位置，直接输出</li><li><strong>时间复杂度</strong>：$O(n + k)$，k = 数值范围</li><li><strong>空间复杂度</strong>：$O(k)$</li><li><strong>稳定性</strong>：稳定</li></ul>',14)])])}const $=r(l,[["render",a]]);export{d as __pageData,$ as default};
